SELECT ?id ?s WHERE {
  ?p brick:hasName ?n .
  ?ref ref:hasTimeseriesId ?s .
  ?ref brick:hasProperty ?p .
  FILTER(?n = "CHWPump01")
}

SELECT ?a ?b WHERE {
  ?x rdf:type ?a . OPTIONAL {?x brick:hasName ?b} . FILTER(CONTAINS(str(?x),"CHWPump"))
}

